def transform(grid):
    n = len(grid)
    m = len(grid[0])

    # In the lower triangle, each column gives the underlying sequence.
    known = {}
    for c in range(min(m, n - 1)):
        vals = [grid[r][c] for r in range(c + 1, n) if grid[r][c] != 0]
        if vals:
            known[c] = max(set(vals), key=vals.count)

    # Find the sequence's repeating period.
    period = max(1, min(n, m))
    for p in range(1, max(n, m) + 1):
        groups = {}
        valid = True
        for i, v in known.items():
            residue = i % p
            if residue in groups and groups[residue] != v:
                valid = False
                break
            groups[residue] = v
        if valid:
            period = p
            break

    groups = {}
    for i, v in known.items():
        groups.setdefault(i % period, []).append(v)
    seq = {}
    for residue, vals in groups.items():
        seq[residue] = max(set(vals), key=vals.count)

    # Fill any unobserved residues by extending the numeric cycle.
    for residue in range(period):
        if residue not in seq:
            prev = (residue - 1) % period
            if prev in seq:
                seq[residue] = seq[prev] % 9 + 1
            else:
                seq[residue] = 1

    def value(index):
        return seq[index % period]

    out = []
    for r in range(n):
        row = []
        for c in range(m):
            # Below the diagonal use the column sequence; on/above it,
            # use the sequence shifted back by one.
            row.append(value(c if r > c else c - 1))
        out.append(row)
    return out
